-- ===== PathVisualization.lua =====
-- PATH VISUALIZATION

local function clearPathVisuals()
    for _, item in ipairs(pathVisualFolder:GetChildren()) do
        item:Destroy()
    end
end

local function createPathPoint(position, index)
    local point = Instance.new("Part")
    point.Name = "Waypoint_" .. index
    point.Shape = Enum.PartType.Ball
    point.Size = Vector3.new(0.4, 0.4, 0.4)
    point.Position = position + Vector3.new(0, 0.25, 0)
    point.Anchored = true
    point.CanCollide = false
    point.CanTouch = false
    point.CanQuery = false
    point.Material = Enum.Material.Neon
    point.Color = PATH_COLOR
    point.Transparency = 0.2
    point.Parent = pathVisualFolder
end

local function createPathLine(a, b, index)
    local distance = (b - a).Magnitude
    if distance <= 0 then
        return
    end

    local segment = Instance.new("Part")
    segment.Name = "Segment_" .. index
    segment.Size = Vector3.new(0.1, 0.1, distance)
    segment.CFrame = CFrame.lookAt((a + b) / 2, b)
    segment.Anchored = true
    segment.CanCollide = false
    segment.CanTouch = false
    segment.CanQuery = false
    segment.Material = Enum.Material.Neon
    segment.Color = PATH_COLOR
    segment.Transparency = 0.35
    segment.Parent = pathVisualFolder
end

local function drawPath(path)
    clearPathVisuals()

    if not viewPathEnabled then
        return
    end

    local waypoints = path:GetWaypoints()
    for index, waypoint in ipairs(waypoints) do
        createPathPoint(waypoint.Position, index)

        if index > 1 then
            createPathLine(waypoints[index - 1].Position, waypoint.Position, index)
        end
    end
end

-- ===== WatermelonTracker.lua =====
-- WATERMELON BOUNDING BOX TRACKER

local function getModelBounds(object)
    if object:IsA("Model") then
        if object.PrimaryPart or object:FindFirstChildWhichIsA("BasePart", true) then
            return object:GetBoundingBox()
        end
    elseif object:IsA("BasePart") then
        return object.CFrame, object.Size
    end

    return nil, nil
end

local function removeTrackedWatermelon(object)
    local data = trackedWatermelons[object]
    if not data then
        return
    end

    if data.Anchor and data.Anchor.Parent then
        data.Anchor:Destroy()
    end

    trackedWatermelons[object] = nil
end

local function markWatermelon(object)
    if trackedWatermelons[object] then
        return
    end

    local boundsCFrame, boundsSize = getModelBounds(object)
    if not boundsCFrame or not boundsSize then
        return
    end

    local anchor = Instance.new("Part")
    anchor.Name = "_WatermelonAnchor"
    anchor.Size = boundsSize
    anchor.CFrame = boundsCFrame
    anchor.Anchored = true
    anchor.CanCollide = false
    anchor.CanTouch = false
    anchor.CanQuery = false
    anchor.Transparency = 1
    anchor.Parent = visualFolder

    local box = Instance.new("BoxHandleAdornment")
    box.Name = "_WatermelonBox"
    box.Adornee = anchor
    box.Size = boundsSize + Vector3.new(0.12, 0.12, 0.12)
    box.Color3 = BOX_COLOR
    box.Transparency = 0.65
    box.AlwaysOnTop = true
    box.ZIndex = 10
    box.Visible = boxesEnabled
    box.Parent = anchor

    local outline = Instance.new("BoxHandleAdornment")
    outline.Name = "_WatermelonOutline"
    outline.Adornee = anchor
    outline.Size = boundsSize + Vector3.new(0.25, 0.25, 0.25)
    outline.Color3 = OUTLINE_COLOR
    outline.Transparency = 0.25
    outline.AlwaysOnTop = true
    outline.ZIndex = 11
    outline.Visible = boxesEnabled
    outline.Parent = anchor

    trackedWatermelons[object] = {
        Anchor = anchor,
        Box = box,
        Outline = outline,
    }

    object.Destroying:Connect(function()
        removeTrackedWatermelon(object)
    end)

    object.AncestryChanged:Connect(function()
        if not object:IsDescendantOf(Workspace) then
            removeTrackedWatermelon(object)
        end
    end)
end

local function checkObject(object)
    if string.lower(object.Name) ~= WATERMELON_NAME then
        return
    end

    if object:IsA("Model") then
        markWatermelon(object)
        return
    end

    local model = object:FindFirstAncestorWhichIsA("Model")
    if model and model ~= Workspace then
        markWatermelon(model)
    else
        markWatermelon(object)
    end
end

local function setBoxesVisible(enabled)
    boxesEnabled = enabled
    updateBoxesToggle()

    for _, data in pairs(trackedWatermelons) do
        data.Box.Visible = enabled
        data.Outline.Visible = enabled
    end
end

toggleBoxesButton.MouseButton1Click:Connect(function()
    setBoxesVisible(not boxesEnabled)
end)

for _, object in ipairs(Workspace:GetDescendants()) do
    checkObject(object)
end

Workspace.DescendantAdded:Connect(checkObject)

task.spawn(function()
    while screenGui.Parent do
        task.wait(SCAN_INTERVAL)

        for _, object in ipairs(Workspace:GetDescendants()) do
            checkObject(object)
        end

        for object, _ in pairs(trackedWatermelons) do
            if not object.Parent or not object:IsDescendantOf(Workspace) then
                removeTrackedWatermelon(object)
            end
        end
    end
end)

-- ===== InteractionHelpers.lua =====
-- GAME INTERACTION HELPER FUNCTIONS

local function clickGiveUpButton()
    local mainInterface = playerGui:FindFirstChild("MainInterface")
    if not mainInterface then return false end

    for _, obj in ipairs(mainInterface:GetDescendants()) do
        if obj:IsA("ImageButton") or obj:IsA("TextButton") then
            local textLabel = obj:FindFirstChildWhichIsA("TextLabel", true)
            if (textLabel and string.find(string.lower(textLabel.Text), "give up")) or
               (obj:IsA("TextButton") and string.find(string.lower(obj.Text), "give up")) then

                setStatus("Giving Up...", Color3.fromRGB(240, 190, 140))

                if typeof(getconnections) == "function" then
                    for _, conn in ipairs(getconnections(obj.Activated)) do
                        if conn.Function then conn.Function() end
                    end
                    for _, conn in ipairs(getconnections(obj.MouseButton1Click)) do
                        if conn.Function then conn.Function() end
                    end
                end

                local pos = obj.AbsolutePosition
                local size = obj.AbsoluteSize
                local inset, _ = GuiService:GetGuiInset()

                local clickX = pos.X + (size.X / 2) + inset.X
                local clickY = pos.Y + (size.Y / 2) + inset.Y

                VirtualInputManager:SendMouseButtonEvent(clickX, clickY, 0, true, game, 0)
                task.wait(0.05)
                VirtualInputManager:SendMouseButtonEvent(clickX, clickY, 0, false, game, 0)

                consecutivePathFailures = 0
                return true
            end
        end
    end
    return false
end

local function findChoiceButtonByText(targetText)
    local mainInterface = playerGui:FindFirstChild("MainInterface")
    if not mainInterface then return nil end

    local dialog = mainInterface:FindFirstChild("Dialog")
    if not dialog then return nil end

    local choices = dialog:FindFirstChild("Choices")
    if not choices then return nil end

    for _, obj in ipairs(choices:GetChildren()) do
        if obj:IsA("TextButton") and obj.Text == targetText then
            return obj
        end
    end
    return nil
end

local function waitForChoiceButton(targetText, timeout, token)
    local startTime = os.clock()
    repeat
        if pathfindingEnabled == false or routineToken ~= token then return nil end
        local button = findChoiceButtonByText(targetText)
        if button then return button end
        task.wait(0.25)
    until os.clock() - startTime >= timeout
    return nil
end

local function clickChoiceButton(button)
    if not button then return end

    if typeof(getconnections) == "function" then
        for _, connection in ipairs(getconnections(button.Activated)) do
            if connection.Function then connection.Function() end
        end
        for _, connection in ipairs(getconnections(button.MouseButton1Click)) do
            if connection.Function then connection.Function() end
        end
    end

    local pos = button.AbsolutePosition
    local size = button.AbsoluteSize
    local inset, _ = GuiService:GetGuiInset()

    local clickX = pos.X + (size.X / 2) + inset.X
    local clickY = pos.Y + (size.Y / 2) + inset.Y

    VirtualInputManager:SendMouseButtonEvent(clickX, clickY, 0, true, game, 0)
    task.wait(0.05)
    VirtualInputManager:SendMouseButtonEvent(clickX, clickY, 0, false, game, 0)
end

-- ===== WatermelonPromptHandler.lua =====
-- PROXIMITY PROMPT & WATERMELON SEARCH

local function triggerPromptEnhanced(prompt)
    if not prompt then return end

    local char = player.Character
    local rootPart = char and char:FindFirstChild("HumanoidRootPart")

    if rootPart and prompt.Parent then
        local targetPart = prompt.Parent
        if targetPart:IsA("Attachment") then targetPart = targetPart.Parent end
        if targetPart and targetPart:IsA("BasePart") then
            rootPart.CFrame = CFrame.new(rootPart.Position, Vector3.new(targetPart.Position.X, rootPart.Position.Y, targetPart.Position.Z))
        end
    end

    task.wait(0.1)
    prompt.HoldDuration = 0

    if typeof(fireproximityprompt) == "function" then
        fireproximityprompt(prompt)
    end

    prompt:InputHoldBegin()
    task.wait(0.05)
    prompt:InputHoldEnd()
end

local function findWatermelonPrompt()
    local topWatermelon = Workspace:FindFirstChild("Watermelon")
    if topWatermelon then
        local innerWatermelon = topWatermelon:FindFirstChild("Watermelon")
        if innerWatermelon then
            local attachment = innerWatermelon:FindFirstChild("Attachment")
            if attachment then
                local prompt = attachment:FindFirstChildWhichIsA("ProximityPrompt")
                if prompt then return prompt, innerWatermelon end
            end
        end
    end

    for targetModel, _ in pairs(trackedWatermelons) do
        local prompt = targetModel:FindFirstChildWhichIsA("ProximityPrompt", true)
        if prompt then
            local part = targetModel:FindFirstChildWhichIsA("BasePart", true) or targetModel.PrimaryPart
            return prompt, part
        end
    end

    for _, obj in ipairs(Workspace:GetDescendants()) do
        if obj:IsA("ProximityPrompt") and string.find(string.lower(obj.Parent.Name), "watermelon") then
            local part = obj.Parent
            if part:IsA("BasePart") then
                return obj, part
            end
        end
    end

    return nil, nil
end

local function spamPromptUntilRemoved(prompt, watermelonPart, token)
    if not prompt or not watermelonPart then return end

    local removed = false
    local destroyConn = watermelonPart.Destroying:Connect(function()
        removed = true
    end)

    local rotSpeed = math.rad(120)
    local startTime = os.clock()

    setStatus("Collecting Watermelon...", Color3.fromRGB(200, 225, 255))

    while not removed and watermelonPart.Parent and pathfindingEnabled and routineToken == token do
        prompt:InputHoldBegin()
        task.wait(0.05)
        prompt:InputHoldEnd()

        if typeof(fireproximityprompt) == "function" then
            fireproximityprompt(prompt)
        end

        local now = os.clock()
        if Camera then
            local center = watermelonPart.Position
            local radius = 6
            local angle = (now - startTime) * rotSpeed

            local newX = center.X + math.cos(angle) * radius
            local newZ = center.Z + math.sin(angle) * radius

            Camera.CFrame = CFrame.new(
                Vector3.new(newX, center.Y + 3, newZ),
                center
            )
        end

        task.wait(0.05)
    end

    if destroyConn then destroyConn:Disconnect() end
end

local function isWithinPromptRange(prompt, watermelonPart)
    if not prompt or not watermelonPart then return false end

    local char = player.Character
    if not char then return false end

    local rootPart = char:FindFirstChild("HumanoidRootPart")
    if not rootPart then return false end

    local maxDist = prompt.MaxActivationDistance or 10
    return (rootPart.Position - watermelonPart.Position).Magnitude <= maxDist
end

