-- AUTO EQUIP ABYSSAL HUNTER

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players = game:GetService("Players")
local GuiService = game:GetService("GuiService")

local LocalPlayer = Players.LocalPlayer
local PlayerGui = LocalPlayer:WaitForChild("PlayerGui")
local ByteNetEvent = ReplicatedStorage:WaitForChild("ByteNetReliable")

local AUTO_EQUIP_SCAN_INTERVAL = 1000
local AUTO_EQUIP_RETRY_INTERVAL = 30
local AUTO_EQUIP_AURA_NAME = "Abyssal Hunter"

local cachedAbyssalHunterButton = nil
local lastAuraScan = 0

-- Preserved local variable for your menu system tracking
local autoEquipEnabled = true 

local function clickGuiObject(object)
    if not object or not object:IsA("GuiObject") then
        return false
    end

    if not object.Visible then
        return false
    end

    local position = object.AbsolutePosition
    local size = object.AbsoluteSize
    local inset = GuiService:GetGuiInset()

    local clickX = position.X + (size.X / 2) + inset.X
    local clickY = position.Y + (size.Y / 2) + inset.Y

    -- Click event logic retained for layout system sync
    game:GetService("VirtualInputManager"):SendMouseButtonEvent(clickX, clickY, 0, true, game, 0)
    task.wait(0.05)
    game:GetService("VirtualInputManager"):SendMouseButtonEvent(clickX, clickY, 0, false, game, 0)

    return true
end

local function findAurasSideButton()
    local mainInterface = PlayerGui:FindFirstChild("MainInterface")
    if not mainInterface then
        return nil
    end

    local sideButtons = mainInterface:FindFirstChild("SideButtons")
    if not sideButtons then
        return nil
    end

    for _, button in ipairs(sideButtons:GetChildren()) do
        if button:IsA("TextButton") or button:IsA("ImageButton") then
            local usageLabel = button:FindFirstChild("Usage", true)

            if usageLabel
                and usageLabel:IsA("TextLabel")
                and usageLabel.Text == "Auras" then

                return button
            end
        end
    end

    return nil
end

local function getAuraPanel()
    local mainInterface = PlayerGui:FindFirstChild("MainInterface")
    if not mainInterface then
        return nil
    end

    local interfaceChildren = mainInterface:GetChildren()
    local auraSection = interfaceChildren[61]
    if not auraSection then
        return nil
    end

    return auraSection
end

local function isAuraMenuOpen()
    local auraPanel = getAuraPanel()
    if not auraPanel or not auraPanel:IsA("GuiObject") then
        return false
    end

    return auraPanel.Visible
end

local function openAurasMenu()
    if isAuraMenuOpen() then
        return true
    end

    local aurasSideButton = findAurasSideButton()
    if not aurasSideButton then
        return false
    end

    if not clickGuiObject(aurasSideButton) then
        return false
    end

    local startedAt = os.clock()
    while os.clock() - startedAt < 2 do
        if isAuraMenuOpen() then
            return true
        end

        task.wait(0.1)
    end

    return false
end

-- Efficient ByteNet custom packet implementation replacing layout tracking logic
local function fireEquipPacket()
    local bytes = { 135, 62, 0, 0 }
    local packetBuffer = buffer.create(#bytes)
    for i = 1, #bytes do
        buffer.writeu8(packetBuffer, i - 1, bytes[i])
    end
    ByteNetEvent:FireServer(packetBuffer, nil)
end

local function tryEquipAbyssalHunter()
    if not autoEquipEnabled then
        return false
    end

    -- Keeps your menu checks performing properly alongside the execution thread
    openAurasMenu()

    if LocalPlayer.Character then
        local currentAura = LocalPlayer.Character:FindFirstChild(AUTO_EQUIP_AURA_NAME)
        
        if not currentAura then
            -- Injecting the corrected `{ 135, 62, 0, 0 }` binary buffer pattern
            fireEquipPacket()
        end
    end
    
    return true
end

-- Fallback loop wrapper safely bound to tracking structures
task.spawn(function()
    while true do
        if autoEquipEnabled then
            tryEquipAbyssalHunter()
        end
        task.wait(AUTO_EQUIP_RETRY_INTERVAL)
    end
end)


-- ===== AutoDevice.lua =====
-- ===== AUTO-DEVICE LOGIC =====

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ByteNetEvent = ReplicatedStorage:WaitForChild("ByteNetReliable")

local BIOME_INTERVAL = 30 * 60  -- 30 minutes
local STRANGE_INTERVAL = 20 * 60  -- 20 minutes

local autoDeviceEnabled = true -- Global macro state variable from your script

-- Raw ByteNet byte definitions
local STRANGE_BYTES = { 34, 1, 0, 0, 0, 18, 0, 83, 116, 114, 97, 110, 103, 101, 32, 67, 111, 110, 116, 114, 111, 108, 108, 101, 114 }
local BIOME_BYTES = { 34, 1, 0, 0, 0, 16, 0, 66, 105, 111, 109, 101, 32, 82, 97, 110, 100, 111, 109, 105, 122, 101, 114 }

-- Universal encoder to prepare memory arrays for network deployment
local function firePacket(byteArray)
	local packetBuffer = buffer.create(#byteArray)
	for i = 1, #byteArray do
		buffer.writeu8(packetBuffer, i - 1, byteArray[i])
	end
	ByteNetEvent:FireServer(packetBuffer, nil)
end

-- Independent, non-blocking execution threads for both devices
local function runBiomeRandomizerLoop()
	while true do
		if autoDeviceEnabled then
			firePacket(BIOME_BYTES)
		end
		task.wait(BIOME_INTERVAL)
	end
end

local function runStrangeControllerLoop()
	while true do
		if autoDeviceEnabled then
			firePacket(STRANGE_BYTES)
		end
		task.wait(STRANGE_INTERVAL)
	end
end

-- Fire immediate execution on activation
task.spawn(function()
	if autoDeviceEnabled then
		firePacket(BIOME_BYTES)
		task.wait(0.5) -- Tiny safety interval to prevent frame congestion
		firePacket(STRANGE_BYTES)
	end
end)

-- Initialize continuous loops
task.spawn(runBiomeRandomizerLoop)
task.spawn(runStrangeControllerLoop)


-- ===== PathfindingEngine.lua =====
-- PATHFINDING & UNSTUCK ENGINE

local function shouldContinue(token)
    return pathfindingEnabled and routineToken == token
end

local function attemptUnstuck(humanoid, rootPart)
    setStatus("Unsticking character...", Color3.fromRGB(240, 200, 120))

    humanoid.Jump = true
    local moveBackVector = -rootPart.CFrame.LookVector * 6 + Vector3.new(math.random(-4, 4), 0, math.random(-4, 4))
    humanoid:MoveTo(rootPart.Position + moveBackVector)

    task.wait(0.8)
end

local function walkToPosition(targetPosition, token)
    local character = player.Character
    if not character then return false end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local rootPart = character:FindFirstChild("HumanoidRootPart")
    if not humanoid or not rootPart then return false end

    while shouldContinue(token) do
        if consecutivePathFailures >= MAX_CONSECUTIVE_FAILURES then
            clickGiveUpButton()
            return false
        end

        local effectiveTarget = targetPosition
        if consecutivePathFailures >= 3 then
            local detourOffset = Vector3.new(
                math.random(-12, 12),
                0,
                math.random(-12, 12)
            )
            effectiveTarget = targetPosition + detourOffset
        elseif consecutivePathFailures > 0 then
            local lightOffset = Vector3.new(
                math.random(-4, 4),
                0,
                math.random(-4, 4)
            )
            effectiveTarget = targetPosition + lightOffset
        end

        local path = PathfindingService:CreatePath(PATH_OPTIONS)
        local computed = pcall(function()
            path:ComputeAsync(rootPart.Position, effectiveTarget)
        end)

        if not computed or path.Status ~= Enum.PathStatus.Success then
            consecutivePathFailures += 1
            setStatus("Path failed (" .. consecutivePathFailures .. "/" .. MAX_CONSECUTIVE_FAILURES .. ")", Color3.fromRGB(240, 140, 150))

            if consecutivePathFailures >= MAX_CONSECUTIVE_FAILURES then
                clickGiveUpButton()
                return false
            end

            attemptUnstuck(humanoid, rootPart)
        else
            drawPath(path)
            setStatus("Walking...", Color3.fromRGB(180, 220, 255))

            local waypoints = path:GetWaypoints()

            local autoJumpConn = nil
            if autoJumpEnabled then
                autoJumpConn = RunService.PreRender:Connect(function()
                    if humanoid and humanoid.Health > 0 then
                        humanoid.Jump = true
                    end
                end)
            end

            local stepFailed = false
            for _, waypoint in ipairs(waypoints) do
                if not shouldContinue(token) or humanoid.Health <= 0 then
                    if autoJumpConn then autoJumpConn:Disconnect() end
                    return false
                end

                if waypoint.Action == Enum.PathWaypointAction.Jump and not autoJumpEnabled then
                    humanoid.Jump = true
                end

                humanoid:MoveTo(waypoint.Position)

                local reached = false
                local finished = false

                local moveConnection = humanoid.MoveToFinished:Connect(function(result)
                    reached = result
                    finished = true
                end)

                local startedAt = os.clock()

                while not finished and shouldContinue(token) do
                    if os.clock() - startedAt >= 6 then
                        break
                    end
                    RunService.Heartbeat:Wait()
                end

                if moveConnection then moveConnection:Disconnect() end

                if not reached then
                    if autoJumpConn then autoJumpConn:Disconnect() end
                    consecutivePathFailures += 1
                    setStatus("Stuck (" .. consecutivePathFailures .. "/" .. MAX_CONSECUTIVE_FAILURES .. ")", Color3.fromRGB(240, 140, 150))

                    attemptUnstuck(humanoid, rootPart)
                    stepFailed = true
                    break
                end
            end

            if autoJumpConn then autoJumpConn:Disconnect() end

            if not stepFailed then
                consecutivePathFailures = 0
                setStatus("Reached target", Color3.fromRGB(200, 230, 255))
                return true
            end
        end
    end

    return false
end

-- ===== AutomationSequences.lua =====
-- AUTOMATION SEQUENCES

local function getLimeTarget()
    local mapFolder = Workspace:WaitForChild("Map", 5)
    if not mapFolder then return nil, nil, nil end

    local limeModel = mapFolder:WaitForChild("Lime", 5)
    if not limeModel then return nil, nil, nil end

    local torso = limeModel:WaitForChild("Torso", 5)
    if not torso then return nil, nil, nil end

    return limeModel, torso.Position, torso:FindFirstChildWhichIsA("ProximityPrompt")
end

local function startWatermelonMinigameSequence(token)
    setStatus("Searching Watermelon...", Color3.fromRGB(240, 220, 160))
    local targetPrompt, watermelonPart = findWatermelonPrompt()
    local startTime = os.clock()

    while not targetPrompt and (os.clock() - startTime < 10) and shouldContinue(token) do
        task.wait(0.5)
        targetPrompt, watermelonPart = findWatermelonPrompt()
    end

    if not targetPrompt or not shouldContinue(token) then
        setStatus("Watermelon missing", Color3.fromRGB(240, 140, 150))
        task.wait(2)
        return
    end

    if watermelonPart and watermelonPart:IsA("BasePart") then
        walkToPosition(watermelonPart.Position, token)
    end

    if not shouldContinue(token) then return end

    task.wait(0.3)
    local freshPrompt, freshPart = findWatermelonPrompt()
    freshPrompt = freshPrompt or targetPrompt
    freshPart = freshPart or watermelonPart

    if freshPrompt and freshPart then
        if not isWithinPromptRange(freshPrompt, freshPart) then
            walkToPosition(freshPart.Position, token)
            task.wait(0.3)

            local recheckPrompt, recheckPart = findWatermelonPrompt()
            freshPrompt = recheckPrompt or freshPrompt
            freshPart = recheckPart or freshPart
        end

        if isWithinPromptRange(freshPrompt, freshPart) and shouldContinue(token) then
            spamPromptUntilRemoved(freshPrompt, freshPart, token)
        end
    end

    updateAttemptsUI()

    task.wait(1)
end

local function executeRoutine(token)
    if not shouldContinue(token) then return end

    local _, limePos, limePrompt = getLimeTarget()
    if not limePos or not limePrompt then
        setStatus("Waiting for Lime...", Color3.fromRGB(160, 168, 185))
        task.wait(1)
        return
    end

    if walkToPosition(limePos, token) then
        if not shouldContinue(token) then return end

        setStatus("Interacting with Lime...", Color3.fromRGB(240, 220, 160))
        triggerPromptEnhanced(limePrompt)

        task.wait(2)
        if not shouldContinue(token) then return end

        local minigameBtn = waitForChoiceButton("[ Minigame ]", 8, token)
        if minigameBtn then
            task.wait(0.5)
            clickChoiceButton(minigameBtn)

            local ticketBtn = waitForChoiceButton("[ -1 Minigame Ticket ]", 8, token)
            if ticketBtn then
                task.wait(0.5)
                clickChoiceButton(ticketBtn)

                task.wait(1)
                if shouldContinue(token) then
                    startWatermelonMinigameSequence(token)
                end
            end
        end
    end
end

-- ===== ControllerExecution.lua =====
-- CONTROLLER EXECUTION & TOGGLES

local function stopRoutine()
    routineToken += 1
    clearPathVisuals()
    setStatus("Idle", Color3.fromRGB(160, 168, 185))
end

local function startRoutineLoop()
    routineToken += 1
    local currentToken = routineToken

    task.spawn(function()
        while pathfindingEnabled and routineToken == currentToken do
            executeRoutine(currentToken)
            task.wait(0.5)
        end
    end)
end

togglePathButton.MouseButton1Click:Connect(function()
    pathfindingEnabled = not pathfindingEnabled
    updatePathToggle()

    if pathfindingEnabled then
        startRoutineLoop()
    else
        stopRoutine()
